/**
 * THESIS: a five-minute argument is a set of drawings, not a set of headlines. Every
 *   sheet dimensions its evidence the way a shop drawing dimensions a part, so the room
 *   reads a measurement before it reads a claim. Refuses the category default — a title
 *   over a picture over a caption — on all five sheets, not just the one with a chart.
 * OWN-WORLD: a drawing set issued two ways. Odd sheets are blueprint — deep forest
 *   ground, mint linework, gold dimensions. Even sheets are whiteprint — bone ground,
 *   green linework, antique gold. Both carry the same frame, the same 45° section hatch,
 *   the same condensed all-caps annotation tracked wide, the same ruled notes row and
 *   three-cell title block. Recognisable with every word removed.
 * STORY: the room opens a drawing set, finds the question on the cover, the measured
 *   problem on sheet 2, the noise floor dimensioned on sheet 3, the schedule of what
 *   changes on sheet 4, and one line to carry out on sheet 5.
 * FIRST VIEWPORT: sheet 1 is a cover — the display line at plan scale on the left, scope
 *   and audience ruled into cells on the right, the drawing's name in the title block.
 * FORM: the tolerance drawing, extended from one sheet to the set. Seed key 24b50457.
 * FINISH: unreviewed and undocumented is unfinished; this build ends with the finish
 *   review, the verdict, and DESIGN.md
 *
 * A direction is a kit, not a rewrite of five decks. Content files declare what kind of
 * visual they need — bars, a noise band, a two-state split — and this file decides how
 * that gets drawn. Nothing here reaches into a deck's narrative.
 *
 * The dark/light alternation is the department's, not this direction's, and it is not
 * optional: deck_qa fails a set that breaks it. Blueprint and whiteprint is how a
 * drawing set honours that rule without inventing a second visual language.
 */
const pptxgen = require("pptxgenjs");
const { C, F } = require("../_kit");

// ── the sheet ──────────────────────────────────────────────────────────────────
const HAIR = 0.012;
const B = { x0: 0.30, y0: 0.26, x1: 9.70, y1: 5.36 };
const PAD = 0.46;
const HEAD_RULE = 0.82;
const DRAW_TOP = 0.94;
const DRAW_BOT = 3.86;
const NOTE_RULE = 3.92;
const TB = 4.60;                    // title block
const DIV_A = 5.55, DIV_B = 7.70;   // the sheet's two vertical divisions

/**
 * Blueprint and whiteprint. Every colour decision on a sheet reads from one of these,
 * so a sheet's ground is the only thing a caller has to choose.
 */
const TONE = {
  dark: {
    ground: C.GROUND_DARK,
    rule: C.MID_GREEN,        // frame and hairlines
    edge: C.MINT_SOFT,        // the heavier boundary of a drawn region
    label: C.MINT,            // small tracked caps
    head: C.MINT_SOFT,        // annotation headings
    body: C.MINT,             // running copy
    display: C.WHITE,         // the claim
    accent: C.GOLD,           // exactly one dimension per sheet
    hatch: C.MINT,
  },
  light: {
    ground: C.GROUND_LIGHT,
    rule: C.BONE_LINE,
    edge: C.GREEN,
    label: C.GRAY_INK,
    head: C.GREEN,
    body: C.GRAY_INK,
    display: C.GREEN,
    accent: C.GOLD_INK,       // Baylor gold is 1.7:1 on bone and never appears there
    hatch: C.GREEN,
  },
};

// Every straight line on these sheets is a filled rect. pptxgenjs 4 writes a 1pt
// #333333 outline onto any shape that asks for no border, so nothing here asks for one.
function line(s, { x, y, w, h, color }) {
  s.addShape("rect", { x, y, w, h, fill: { color }, line: { color, width: 0.25 } });
}
const hrule = (s, x, y, w, color) => line(s, { x, y, w, h: HAIR, color });
const vrule = (s, x, y, h, color, t = HAIR) => line(s, { x, y, w: t, h, color });

/** A drafting arrowhead. `dir` is the direction it points. */
function arrow(s, { x, y, dir, color, size = 0.12 }) {
  s.addShape("triangle", {
    x: x - size / 2, y: y - size / 2, w: size, h: size,
    fill: { color }, line: { color, width: 0.25 },
    rotate: dir === "left" ? 270 : 90,
  });
}

/** 45° section hatch, clipped to the rect. Drafting says "this region is excluded". */
function hatch(s, { x, y, w, h, step = 0.18, color, width = 0.5 }) {
  for (let k = -h; k < w; k += step) {
    const t0 = Math.max(-k, 0);
    const t1 = Math.min(w - k, h);
    if (t1 - t0 < 0.02) continue;
    s.addShape("line", {
      x: x + k + t0, y: y + t0, w: t1 - t0, h: t1 - t0,
      line: { color, width },
    });
  }
}

/**
 * A drafting centreline: long dash, short dash, repeat.
 *
 * Heavier and brighter than any adjustable line on the sheet, on purpose. A datum is
 * measured and a threshold is chosen, and that distinction cannot rest on dash rhythm,
 * which does not survive a projector.
 */
function centreline(s, { x, y0, y1, color }) {
  let y = y0;
  let long = true;
  while (y < y1) {
    const seg = Math.min(long ? 0.17 : 0.05, y1 - y);
    vrule(s, x, y, seg, color, 0.020);
    y += seg + 0.055;
    long = !long;
  }
}

function label(s, text, { x, y, w, color, size = 8, align = "left", face = F.COND, h = 0.20 }) {
  s.addText(text.toUpperCase(), {
    x, y, w, h, fontSize: size, fontFace: face, color, align,
    charSpacing: 1.1, valign: "top", margin: 0,
  });
}

function body(s, text, { x, y, w, h, color, size = 10.5, italic = false }) {
  s.addText(text, {
    x, y, w, h, fontSize: size, fontFace: F.BODY_LIGHT, color, italic,
    valign: "top", margin: 0, lineSpacingMultiple: 1.12,
  });
}

/**
 * The chrome every sheet in the set shares: frame, header rule, notes rule, title
 * block. Drawn first so a sheet's own content sits on top of it, and identical on all
 * five so the set reads as one drawing rather than five slides.
 */
function sheet(pres, d, { n, caption, title, dark }) {
  const T = dark ? TONE.dark : TONE.light;
  const s = pres.addSlide();
  s.background = { color: T.ground };

  hrule(s, B.x0, B.y0, B.x1 - B.x0, T.rule);
  hrule(s, B.x0, B.y1, B.x1 - B.x0, T.rule);
  vrule(s, B.x0, B.y0, B.y1 - B.y0, T.rule);
  vrule(s, B.x1, B.y0, B.y1 - B.y0, T.rule);
  hrule(s, B.x0, HEAD_RULE, B.x1 - B.x0, T.rule);

  label(s, caption, { x: PAD, y: 0.46, w: 5.0, color: T.label, size: 9 });
  label(s, `${d.topic} · 5 Slides in 5 Minutes`,
    { x: 5.90, y: 0.46, w: 3.66, color: T.label, size: 9, align: "right" });

  // The foot is one structure: the notes rule and the title block share two divisions.
  hrule(s, B.x0, NOTE_RULE, B.x1 - B.x0, T.rule);
  vrule(s, DIV_A, NOTE_RULE, B.y1 - NOTE_RULE, T.rule);
  vrule(s, DIV_B, NOTE_RULE, B.y1 - NOTE_RULE, T.rule);
  hrule(s, B.x0, TB, B.x1 - B.x0, T.rule);

  label(s, "Title", { x: PAD, y: TB + 0.05, w: 2.0, color: T.label, size: 7.5 });
  s.addText(title, {
    x: PAD, y: TB + 0.19, w: 5.02, h: 0.54, fontSize: 21, fontFace: F.COND_MED,
    color: T.display, valign: "top", margin: 0, lineSpacingMultiple: 1.02,
  });

  label(s, "Subject", { x: 5.71, y: TB + 0.05, w: 1.9, color: T.label, size: 7.5 });
  s.addText(d.topic, {
    x: 5.71, y: TB + 0.19, w: 1.9, h: 0.22, fontSize: 10, fontFace: F.COND_MED,
    color: T.head, valign: "top", margin: 0,
  });
  s.addText("Baylor Athletics · Applied Performance", {
    x: 5.71, y: TB + 0.42, w: 1.9, h: 0.20, fontSize: 7.5, fontFace: F.BODY_LIGHT,
    color: T.body, valign: "top", margin: 0,
  });

  label(s, "Sheet", { x: 7.86, y: TB + 0.05, w: 1.7, color: T.label, size: 7.5 });
  s.addText(`${n} / 5`, {
    x: 7.86, y: TB + 0.19, w: 1.7, h: 0.26, fontSize: 13, fontFace: F.COND,
    color: T.head, valign: "top", margin: 0, charSpacing: 1,
  });

  return { s, T };
}

/** The three general-note cells, on the sheet's own divisions. */
function notes(s, T, cells) {
  const cols = [
    { x: PAD, w: 4.93, size: 9 },
    { x: 5.71, w: 1.83, size: 8.5 },
    { x: 7.86, w: 1.68, size: 8 },
  ];
  cells.forEach((text, i) => {
    if (!text) return;
    const c = cols[i];
    label(s, `Note ${i + 1}`, { x: c.x, y: NOTE_RULE + 0.04, w: 1.2, h: 0.12, color: T.head, size: 8 });
    body(s, text, { x: c.x, y: NOTE_RULE + 0.17, w: c.w, h: 0.44, size: c.size, color: T.body });
  });
}

