 * Deal a deck's footnote across the three note cells, by sentence.
 *
 * A drawing's general notes are numbered and separate, and the deck already writes its
 * footnote as a sequence of complete thoughts. Distributing them keeps the narrative in
 * the content file — the kit decides where prose goes, never what it says.
 */
function dealNotes(text, counts) {
  const parts = (text || "").match(/[^.]+\./g) || [text];
  const out = [];
  let i = 0;
  counts.forEach((n) => {
    out.push(parts.slice(i, i + n).join(" ").trim());
    i += n;
  });
  if (i < parts.length) out[out.length - 1] += ` ${parts.slice(i).join(" ").trim()}`;
  return out;
}

// ── the noise-band sheet, drawn as a tolerance ─────────────────────────────────
const AX0 = 2.90, AX1 = 9.20, SPAN = 14;           // −7 % … +7 %
const U = (AX1 - AX0) / SPAN;
const ZERO = AX0 + 7 * U;
const xOf = (pct) => ZERO + pct * U;
const AY = 2.90;                                    // axis line
const ZTOP = 1.88;                                  // hatched zone, top
const COL = { x: PAD, w: 1.94, divider: 2.56 };     // the notes column

/** First line of a deck's band caption is its heading; the rest is its body. */
const headOf = (t) => (t || "").split("\n")[0];
const restOf = (t) => (t || "").split("\n").slice(1).join(" ").replace(/\s+/g, " ").trim();

/**
 * Typical error, drawn as a manufacturing tolerance.
 *
 * The band is not shaded with its explanation typeset inside it. It is a hatched zone
 * dimensioned from a measured datum, with the explanation displaced to a notes column —
 * which is where a drawing puts prose. The threshold is a separate, dashed, adjustable
 * line, because it is chosen rather than measured, and that is the sheet's whole
 * argument.
 */
function toleranceDrawing(s, T, o) {
  const te = o.typicalError || 3.0;
  const XA = xOf(-te), XB = xOf(te);

  vrule(s, COL.divider, DRAW_TOP, DRAW_BOT - DRAW_TOP - 0.16, T.rule);

  label(s, "Inside the noise floor",
    { x: COL.x, y: 1.10, w: COL.w, color: T.head, size: 10, face: F.COND_MED });
  body(s, restOf(o.inside), { x: COL.x, y: 1.32, w: COL.w, h: 0.84, size: 10.5, color: T.body });

  hrule(s, COL.x, 2.20, COL.w, T.rule);
  label(s, "The dashed line", { x: COL.x, y: 2.30, w: COL.w, color: T.head, size: 10, face: F.COND_MED });
  body(s, "Set by which error costs more. Not by the data.",
    { x: COL.x, y: 2.52, w: COL.w, h: 0.44, size: 10.5, color: T.body });

  if (o.source) {
    hrule(s, COL.x, 3.04, COL.w, T.rule);
    label(s, "Source", { x: COL.x, y: 3.14, w: COL.w, color: T.label, size: 8 });
    body(s, o.source, { x: COL.x, y: 3.30, w: COL.w, h: 0.42, size: 9, color: T.body });
  }

  hatch(s, { x: XA, y: ZTOP, w: XB - XA, h: AY - ZTOP, color: T.hatch });
  hrule(s, XA, ZTOP, XB - XA, T.edge);
  vrule(s, XA, 1.68, 2.98 - 1.68, T.edge);
  vrule(s, XB, 1.68, 2.98 - 1.68, T.edge);

  // The dimension, split at the centreline so a full-span arrow can never be read as
  // one double-width quantity. The one accent on the sheet.
  s.addText("TYPICAL ERROR", {
    x: ZERO - 1.60, y: 1.00, w: 3.20, h: 0.28, fontSize: 15, fontFace: F.COND,
    bold: true, color: T.accent, align: "center", charSpacing: 1.6, valign: "top", margin: 0,
  });
  if (o.errorNote) {
    label(s, o.errorNote, { x: ZERO - 2.00, y: 1.29, w: 4.00, color: T.body, size: 8.5, align: "center" });
  }
  [[XA, ZERO, "left"], [ZERO, XB, "right"]].forEach(([x0, x1, outward]) => {
    hrule(s, x0 + 0.06, 1.76, x1 - x0 - 0.06, T.accent);
    arrow(s, { x: outward === "left" ? x0 + 0.07 : x1 - 0.07, y: 1.766, dir: outward, color: T.accent });
    s.addText(`${te.toFixed(1)} %`, {
      x: (x0 + x1) / 2 - 0.45, y: 1.46, w: 0.90, h: 0.24, fontSize: 11, fontFace: F.COND_MED,
      color: T.accent, align: "center", valign: "top", margin: 0,
    });
  });
  vrule(s, ZERO, 1.70, 0.14, T.accent);
  centreline(s, { x: ZERO, y0: 1.92, y1: 2.94, color: T.display });

  // The threshold: dashed on both sides, because a person sets it and it is symmetric.
  const XT = o.thresholdAt || te * 1.5;
